struct ProjectsView: View {
    @EnvironmentObject private var store: AppStore
    @State private var statusFilter: ProjectStatus?

    private var projectItems: [ProjectEvidenceBoardItem] {
        var grouped: [UUID: [(link: ProjectLink, record: HistoryRecord)]] = [:]
        for record in store.historyRecords {
            for link in record.projectLinks {
                grouped[link.projectId, default: []].append((link, record))
            }
        }

        return grouped.map { projectId, entries in
            ProjectEvidenceBoardItem(
                id: projectId,
                name: store.projectNames[projectId] ?? "未命名长期议题",
                entries: entries
            )
        }
        .sorted { $0.latestDate > $1.latestDate }
    }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 0) {
                    projectHeader

                    VStack(alignment: .leading, spacing: 16) {
                        if store.hasResumeableLoop && !store.isResumeBannerDismissed {
                            ResumeTodayRow()
                        }

                        ProjectCurrentFocus(
                            title: store.mainQuest?.title ?? "还没有生成主线任务",
                            detail: store.mainQuest?.completionCriteria ?? "完成今日复盘后，明日任务会成为项目推进的临时焦点。",
                            canCreateProject: store.canCreateProjectFromCurrentFocus,
                            createProject: {
                                Task {
                                    await store.createProjectFromCurrentFocus()
                                }
                            }
                        )

                        projectsCandidateReviewSection
                        projectMergeReviewSection

                        projectBoard
                    }
                    .padding(.horizontal, DS.pagePadding)
                    .padding(.top, 18)
                    .padding(.bottom, DS.primaryScrollBottomReserve)
                }
            }
            .scrollIndicators(.hidden)
            .background(DS.background.ignoresSafeArea())
            .task {
                await store.loadHistoryRecords()
                await store.loadPendingProjectMergeCandidates()
            }
        }
        .background(DS.background.ignoresSafeArea())
        .topSafeAreaScrim()
    }

    private var projectHeader: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("项目")
                .font(.system(size: 28, weight: .bold, design: .rounded))
                .foregroundStyle(DS.ink)
            Text("不是文件夹，也不是关键词聚类；这里只放被历史证据支撑的长期议题。")
                .font(.subheadline)
                .foregroundStyle(DS.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, DS.pagePadding)
        .padding(.top, 12)
        .padding(.bottom, 10)
        .background(DS.background)
    }

    @ViewBuilder
    private var projectBoard: some View {
        let filtered = projectStatusFilteredItems(projectItems, projectsById: store.projectsById, status: statusFilter)
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .firstTextBaseline) {
                SectionLabel("项目工作台")
                Spacer()
                Text(projectBoardCountText(filteredCount: filtered.count, totalCount: projectItems.count, filterStatus: statusFilter))
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(DS.mutedInk)
            }

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    statusFilterChip(label: "全部", isSelected: statusFilter == nil) {
                        statusFilter = nil
                    }
                    ForEach(ProjectStatus.allCases) { status in
                        statusFilterChip(label: status.chineseTitle, isSelected: statusFilter == status) {
                            statusFilter = status
                        }
                    }
                }
            }

            if projectItems.isEmpty {
                ProjectEmptyEvidenceState()
            } else if filtered.isEmpty {
                Text("没有匹配「\(statusFilter?.chineseTitle ?? "")」状态的项目。")
                    .font(.subheadline)
                    .foregroundStyle(DS.mutedInk)
                    .frame(maxWidth: .infinity, alignment: .center)
                    .padding(.vertical, 24)
            } else {
                ForEach(filtered) { item in
                    NavigationLink {
                        ProjectDetailView(
                            item: item,
                            project: store.projectsById[item.id]
                        )
                    } label: {
                        ProjectEvidenceBoardRow(item: item)
                    }
                    .buttonStyle(.plain)
                }
            }
        }
    }

    private func statusFilterChip(label: String, isSelected: Bool, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Text(label)
                .font(.caption.weight(isSelected ? .semibold : .regular))
                .foregroundStyle(isSelected ? DS.accent : DS.mutedInk)
                .padding(.horizontal, 12)
                .padding(.vertical, 6)
                .background(
                    RoundedRectangle(cornerRadius: 8)
                        .fill(isSelected ? DS.accent.opacity(0.12) : Color.clear)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8)
                        .strokeBorder(isSelected ? DS.accent.opacity(0.3) : DS.mutedInk.opacity(0.2), lineWidth: 1)
                )
        }
        .buttonStyle(.plain)
    }

    @ViewBuilder
    private var projectsCandidateReviewSection: some View {
        let pendingCandidates = store.projectCandidates.filter { $0.status == .pending }
        let pendingLinks = store.projectLinkCandidates
        if !pendingCandidates.isEmpty || !pendingLinks.isEmpty {
            VStack(alignment: .leading, spacing: 12) {
                HStack {
                    SectionLabel("待确认候选")
                    Spacer()
                    Text("\(pendingCandidates.count + pendingLinks.count) 条")
                        .font(.caption.monospacedDigit())
                        .foregroundStyle(DS.mutedInk)
                }

                ForEach(pendingCandidates) { candidate in
                    ProjectCandidateReviewRow(
                        candidate: candidate,
                        onAccept: {
                            Task { await store.acceptProjectCandidate(candidate) }
                        },
                        onDismiss: {
                            Task { await store.dismissProjectCandidate(candidate) }
                        }
                    )
                }
                ForEach(pendingLinks) { link in
                    ProjectLinkCandidateRow(
                        candidate: link,
                        projectName: link.projectId.flatMap { store.projectNames[$0] },
                        onAccept: {
                            Task { await store.acceptProjectLinkCandidate(link) }
                        },
                        onDismiss: {
                            store.dismissProjectLinkCandidate(link)
                        }
                    )
                }
            }
        }
    }

      ]
    }
    """.utf8
)

// MARK: - Visual QA Launch Fixture

func testVisualQAProjectDetailFixture_startsOnProjectsTab() {
    let fixtureStore = AppStore.visualQAProjectDetail()
    XCTAssertEqual(fixtureStore.selectedTab, .projects)
}

func testVisualQAProjectDetailFixture_hasAtLeastOneEvidenceBackedProject() {
    let fixtureStore = AppStore.visualQAProjectDetail()
    XCTAssertFalse(fixtureStore.projectsById.isEmpty, "Fixture must include at least one project in projectsById")
    XCTAssertFalse(fixtureStore.projectNames.isEmpty, "Fixture must include project names")

    let project = fixtureStore.projectsById.values.first!
    let projectId = project.id
    XCTAssertEqual(fixtureStore.projectNames[projectId], project.name)

    let hasConfirmedLink = fixtureStore.historyRecords.contains { record in
        record.projectLinks.contains { link in
            link.projectId == projectId && link.isUserConfirmed
        }
    }
    XCTAssertTrue(hasConfirmedLink, "Fixture must have at least one history record with a confirmed ProjectLink for the project")
}

func testVisualQAProjectDetailFixture_hasProjectInsights() {
    let fixtureStore = AppStore.visualQAProjectDetail()
    let allInsights = fixtureStore.acceptedProjectInsights + fixtureStore.pendingProjectInsights
    XCTAssertFalse(allInsights.isEmpty, "Fixture must have accepted or pending project insights")

    let projectIds = Set(fixtureStore.projectsById.keys)
    XCTAssertTrue(
        allInsights.allSatisfy { projectIds.contains($0.projectId) },
        "All fixture insights must reference a project in projectsById"
    )
}

func testVisualQAProjectDetailLaunch_withoutArgument_returnsFalse() {
    let cleanDefaults = UserDefaults(suiteName: "test-visual-qa-no-argument")!
    cleanDefaults.removeObject(forKey: "MINGSI_VISUAL_QA_PROJECT_DETAIL")
    XCTAssertFalse(
        AppStore.isVisualQAProjectDetailLaunch(
            arguments: [],
            environment: [:],
            defaults: cleanDefaults,
            markerFileExists: { false }
        ),
        "Without MINGSI_VISUAL_QA_PROJECT_DETAIL, fixture mode should not activate"
    )
    cleanDefaults.removeSuite(named: "test-visual-qa-no-argument")
}

func testVisualQAProjectDetailLaunch_withArgument_returnsTrue() {
    XCTAssertTrue(
        AppStore.isVisualQAProjectDetailLaunch(arguments: ["MINGSI_VISUAL_QA_PROJECT_DETAIL"]),
        "With MINGSI_VISUAL_QA_PROJECT_DETAIL, fixture mode should activate"
    )
}

