        switch kind {
        case .project:
            return 136
        case .lens:
            return 128
        case .cardType, .questStatus:
            return 118
        }
    }
}

struct HistoryView: View {
    @EnvironmentObject private var store: AppStore
    @State private var selectedDate = Date()
