    private func candidateStatusColor(_ status: HistoricalRetryCandidateStatus) -> Color {
        switch status {
        case .pending, .retrying:
            return DS.mutedInk
        case .candidateReady:
            return DS.accent
        case .accepted:
            return DS.success
        case .dismissed:
            return DS.mutedInk
        case .blocked:
            return DS.caution
        case .failed:
            return DS.caution
        }
    }

