                            }
                        )
                    }
                }
            }

            if accepted.isEmpty && pending.isEmpty && store.projectInsightGenerationMessage.isEmpty && !store.isGeneratingProjectInsights {
                ProjectInsightNote(message: "还没有经过确认的项目洞察。先积累并确认几条项目证据，再让 AI 提出候选。")
